import json
import os
import re

from orca_task_sdk import run_orca

XYZ_NAME = "ethanol.xyz"
INPUT_NAME = "job.inp"
REQUEST_KEY = "ethanol-opt-freq-1"

def build_input():
    return """! B3LYP 6-31G* Opt Freq TightSCF NORI NoAutoStart RKS
%pal
  nprocs 4
end
%maxcore 192
%scf
  MaxIter 256
  ConvForced true
  AutoTRAH false
end
%geom
  MaxIter 128
  EnforceStrictConvergence true
end
%method
  Z_MaxIter 128
end
* xyzfile 0 1 ethanol.xyz
"""

def read_from_files(files, predicate):
    for original_name, path in files.items():
        if predicate(original_name):
            try:
                with open(path, "r", encoding="utf-8", errors="replace") as handle:
                    return original_name, handle.read()
            except OSError:
                continue
    return None, ""

def parse_frequencies(text):
    values = []
    in_block = False
    pattern = re.compile(r"^\s*(\d+):\s+(-?\d+\.\d+)\s+cm\*\*-1")
    for line in text.splitlines():
        if "VIBRATIONAL FREQUENCIES" in line:
            in_block = True
            continue
        if not in_block:
            continue
        if "NORMAL MODES" in line or "IR SPECTRUM" in line:
            break
        match = pattern.match(line)
        if match:
            values.append(float(match.group(2)))
    return values

with open(INPUT_NAME, "w", encoding="utf-8") as handle:
    handle.write(build_input())

receipt = run_orca(INPUT_NAME, dependencies=(XYZ_NAME,), request_key=REQUEST_KEY)
files = receipt.get("files", {})

optimized_name, optimized_text = read_from_files(
    files, lambda name: name.endswith("job.xyz")
)
if not optimized_text:
    optimized_name, optimized_text = read_from_files(
        files, lambda name: name.endswith(".xyz") and not name.endswith(XYZ_NAME)
    )

stdout_name, stdout_text = read_from_files(
    files, lambda name: name.endswith("stdout.out") or name.endswith("job.out")
)
frequencies = parse_frequencies(stdout_text)

observations = {
    "version": 1,
    "observations": [
        {
            "name": "optimized_geometry",
            "value": optimized_text,
            "unit": None,
            "sources": [
                {
                    "internal_request_key": receipt.get("request_key", REQUEST_KEY),
                    "filename": optimized_name or "job.xyz",
                    "location": "final optimized geometry",
                }
            ],
            "limitations": [
                "B3LYP/6-31G* gas-phase optimization; not a basis-set-limit benchmark"
            ],
        },
        {
            "name": "vibrational_frequencies",
            "value": frequencies,
            "unit": "cm^-1",
            "sources": [
                {
                    "internal_request_key": receipt.get("request_key", REQUEST_KEY),
                    "filename": stdout_name or "stdout.out",
                    "location": "VIBRATIONAL FREQUENCIES block",
                }
            ],
            "limitations": [
                "harmonic frequencies from ORCA Freq; no anharmonic correction"
            ],
        },
    ],
}

with open("observations.json", "w", encoding="utf-8") as handle:
    json.dump(observations, handle, indent=2, allow_nan=False)
print(json.dumps({"request_key": receipt.get("request_key"), "files": list(files.keys()), "frequency_count": len(frequencies)}))

